IF @price > 100
BEGIN
    PRINT 'Expensive item';
    SET @category = 'Premium';
    SET @priority = 1;
END

DECLARE @counter INT = 1;

WHILE @counter <= 5
BEGIN
    PRINT 'Iteration ' + CAST(@counter AS VARCHAR(10));
    SET @counter = @counter + 1;
END;

DECLARE @i INT = 1;

WHILE @i <= 10
BEGIN
    IF @i > 7
        BREAK;  -- exit the loop entirely
    IF @i % 2 = 0
    BEGIN
        SET @i = @i + 1;
        CONTINUE;  -- skip even numbers
    END
    PRINT CAST(@i AS VARCHAR(10));
    SET @i = @i + 1;
END;

-- Wait 10 seconds
WAITFOR DELAY '00:00:10';

-- Wait until 9:00 AM
WAITFOR TIME '09:00:00';
